func (_q *RelationshipQuery) loadWorkspace(ctx context.Context, query *RevenueWorkspaceQuery, nodes []*Relationship, init func(*Relationship), assign func(*Relationship, *RevenueWorkspace)) error {
	ids := make([]uuid.UUID, 0, len(nodes))
	nodeids := make(map[uuid.UUID][]*Relationship)
	for i := range nodes {
		if nodes[i].revenue_workspace_id == nil {
			continue
		}
		fk := *nodes[i].revenue_workspace_id
		if _, ok := nodeids[fk]; !ok {
			ids = append(ids, fk)
		}
		nodeids[fk] = append(nodeids[fk], nodes[i])
	}
	if len(ids) == 0 {
		return nil
	}
	query.Where(revenueworkspace.IDIn(ids...))
	neighbors, err := query.All(ctx)
	if err != nil {
		return err
	}
	for _, n := range neighbors {
		nodes, ok := nodeids[n.ID]
		if !ok {
			return fmt.Errorf(`unexpected foreign-key "revenue_workspace_id" returned %v`, n.ID)
		}
		for i := range nodes {
			assign(nodes[i], n)
		}
	}
	return nil
}
